 ".join(parts) return ( f"[out:json][timeout:{timeout}];
" f"(
 {body}
);
" f"out geom;
" )

def _build_query(south: float, west: float, north: float, east: float, timeout: int = 30) -> str: bbox = f"{south},{west},{north},{east}" parts = [] for key in LANDMARK_KEYS: for kind in ("node", "way", "relation"): parts.append(f'{kind}["{key}"]["name"]({bbox});') body = "
 ".join(parts) return f"[out:json][timeout:{timeout}];
(
 {body}
);
out center tags;
