") return if got is None: # why not (a diagnostic): <path>.skipped, one line a building style, kind, uses = job[8] or {}, job[5], job[13] info = style.get("uk_rooms") or {} why = ("no record" if not info else f"kind={kind} uses={len(uses or [])} " f"dwelling={info.get('dwelling')} look={info.get('look')} levels={job[2]}") with open(f"{path}.skipped", "a", encoding="utf-8") as f: f.write(f"{job[9]}	{why}
") return house, prog, bid = got style = job[8] or {} rec = {"id": bid, "label": job[9], "programme": prog, "style": style.get("name"), "rooms": style.get("uk_rooms"), "width": house.width, "height": house.height, "masks": ["/".join("".join("1" if v else "0" for v in row) for row in m) for m in house.masks], "street": house.street, "party": sorted(house.party), "garage": house.garage, "epc_rooms": house.epc_rooms, "homes": house.homes} with open(f"{path}.{os.getpid()}", "a", encoding="utf-8") as f: f.write(json.dumps(rec) + "
