def configure_tools(tools: Path, game: Path | None) -> None: step(4, "Tile artwork and tool configuration") config_dir = tools / "config" tiles_dir = tools / "Tiles" two_x = tiles_dir / "2x" two_x.mkdir(parents=True, exist_ok=True) # The editors store absolute folder paths, so they have to be written for # wherever the tools landed on this PC. settings = tools / "settings" settings.mkdir(exist_ok=True) ini = settings / "PZTools.ini" # The game folder too: the editor reads the game's tile definitions from # it, and without them every window - a floor-to-ceiling glass panel as # much as a small sash - got a small house-window hole cut in the wall, so # tall windows showed wall behind the glass. A Steam library off the # default drive is not found by the editor's own search. # The editor appends "media" to this itself, so it wants the folder above # the media folder - which on a Mac is inside the application bundle, not # the game folder. And every path here has to be spelled the way the # editor will read it: one running under Wine cannot open /Users/somebody. media = knoxpaths.pz_media_dir(game) if game else None def ini_path(path: Path) -> str: return path.as_posix() if os.name == "nt" else knoxpaths.tool_path(path) game_line = f"ProjectZomboidDirectory={ini_path(media.parent)}
" if media else "" ini.write_text("[%General]
SettingsSchema=2

[Paths]
" f"ConfigDirectory={ini_path(config_dir)}
" f"TilesDirectory={ini_path(tiles_dir)}
" + game_line, encoding="utf-8") say(" editor paths written") if game is None: say(" skipped tile extraction - no game folder. Run Setup again once " "it is installed.") else: from tools import extract_tiles, prune_tilesets # Wherever this system keeps the game's artwork - inside the application # bundle on a Mac, in <game>/media everywhere else. packs = knoxpaths.pz_media_dir(game) / "texturepacks" tilesets = config_dir / "Tilesets.txt" # Start again from the full catalogue, so a sheet pruned by an earlier run # (say, before the game was updated) gets another chance to be extracted. full = config_dir / "Tilesets.txt.pre-prune" if full.exists(): shutil.copyfile(full, tilesets) ensure_tree_catalogue(tilesets) ensure_road_catalogue(tilesets) catalog, _packs = extract_tiles.read_tilesets_txt(str(tilesets)) # Sheets extracted before the split-sheet fix lack the tiles B42 keeps in # the floor packs - flat roof tops among them - so merge those in once, # or whenever the game's floor packs are updated. merged = tools / "settings" / "floor_tiles_merged" floor_packs = sorted(packs.glob("*2x.floor.pack")) needs_floor_merge = not merged.exists() if not needs_floor_merge and floor_packs: merged_mtime = merged.stat().st_mtime if any(p.stat().st_mtime > merged_mtime for p in floor_packs): needs_floor_merge = True present = sorted(n for n in catalog if (two_x / f"{n}.png").exists()) if present and needs_floor_merge: say(" adding Build 42 floor-pack tiles to your tile sheets ...") log = io.StringIO() with contextlib.redirect_stdout(log): for pack in floor_packs: extract_tiles.extract_pack(str(pack), catalog, set(present), str(two_x), merge=True) merged.parent.mkdir(parents=True, exist_ok=True) merged.write_text("1", encoding="utf-8") missing = sorted(n for n in catalog if not (two_x / f"{n}.png").exists()) if missing: say(f" extracting {len(missing)} tile sheets from your game (a few minutes) ...") log = io.StringIO() with contextlib.redirect_stdout(log): extract_tiles.main(["extract_tiles", str(packs), str(tilesets), str(two_x), *missing]) (tools / "settings" / "extract_tiles.log").write_text(log.getvalue(), encoding="utf-8") merged.write_text("1", encoding="utf-8") # main() merges the floor packs itself found = sum(1 for n in missing if (two_x / f"{n}.png").exists()) say(f" extracted {found} of {len(missing)}" + ("" if found == len(missing) else f" - {len(missing) - found} no longer exist in Build 42, which is fine")) else: say(" tile sheets already extracted") # Sheets Build 42 no longer ships would otherwise be retried by the # editor on every building it loads, stalling compiles for minutes. with contextlib.redirect_stdout(io.StringIO()): prune_tilesets.main(["prune_tilesets", str(tilesets), str(two_x)]) add_erikas_tiles(tools, tilesets, two_x) # The rules last, and whether or not there is a game: the kerbs and street # furniture need no artwork, and the tree rules say what they are missing # if they do. Skipping the whole step on a PC without the game left both # red with nothing on screen to say why. if game is None: say(" Note: Big trees and tree rules require tile artwork from Project Zomboid.") say(" They will be configured once Setup is run with your game folder located.") patch_rules(tools)

