def main(argv: list[str]) -> int: global TILES_2X args = [a for a in argv[1:] if not a.startswith("--")] if len(args) < 2: print(__doc__) return 2 cfg_dir, out_path = args[0], args[1] if Path(out_path).resolve() == COMMITTED and "--force" not in argv: print(f"refusing to write {out_path}", file=sys.stderr) print(" It is the catalog KnoxMap builds with, and it carries sections this " "generator does not write:
