]*)$", body, re.M) tiles = {k: v.strip() for k, v in pairs if k != "offset" and v.strip()} if tiles and next(iter(tiles.values())) == anchor: return {"category": category, "tiles": tiles} raise SystemExit(f"ERROR: no {category} {anchor!r} in BuildingTiles.txt.") # BuildingEd draws a window as a frame and glass with nothing behind it: # the hole in the wall is the wall's own cut-out tile, one per window # style - WestWindow for the first, WestWindow1..19 for the rest. A wall # entry that names only the first leaves every other window standing in # mid-air, which is what happened on the north and west face of every # building, the two sides BuildingEd walls with the room's interior wall. # BuildingTemplates.txt names only the first; BuildingTiles.txt has them # all, so a wall taken from the templates is filled in from there. ALT_WINDOWS = 19 def bt_lookup(category: str, anchor: str) -> dict | None: """bt_entry, but nothing rather than a hard stop when it is not there.""" try: return bt_entry(category, anchor) except (SystemExit, ValueError): return None def with_cutouts(entry: dict | None) -> dict | None: """A wall entry that has a cut-out for every window style.""" if not entry or not entry.get("category", "").endswith("_walls"): return entry tiles = dict(entry["tiles"]) if "WestWindow1" in tiles: return entry anchor = next(iter(tiles.values()), None) full = bt_lookup(entry["category"], anchor) if anchor else None if full: tiles = dict(full["tiles"]) if "WestWindow1" in tiles: return {"category": entry["category"], "tiles": tiles} # The editor's list has no alternates for this wall either - a shop # front, or one of the sheets that carries a single opening. Every # window then opens the same one, which is wrong by a few pixels and # right by a whole wall. for side in ("West", "North"): plain = tiles.get(f"{side}Window") or tiles.get(side) if plain: for n in range(1, ALT_WINDOWS + 1): tiles[f"{side}Window{n}"] = plain return {"category": entry["category"], "tiles": ti