def write_spawn_pyramid(project_dir: str, map_dir: str) -> bool: """spawnSelectImagePyramid.zip from the map's preview. False without one.""" import io import zipfile from PIL import Image sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__)))) from tools.terrain_source import project_origin name = os.path.basename(os.path.normpath(project_dir)) preview = os.path.join(project_dir, f"{name}_preview.png") if not os.path.exists(preview): return False Image.MAX_IMAGE_PIXELS = None # a town's preview is a pixel a tile with Image.open(preview) as src: w, h = src.size # tiles: the preview is one pixel to a tile scale = min(1.0, SPAWN_PICTURE_MAX_PX / max(w, h)) image = src.convert("RGBA").resize( (max(1, round(w * scale)), max(1, round(h * scale))), Image.LANCZOS) ox, oy = project_origin(project_dir) with zipfile.ZipFile(os.path.join(map_dir, "spawnSelectImagePyramid.zip"), "w", zipfile.ZIP_STORED) as z: z.writestr("pyramid.txt", "VERSION=1
" f"bounds={ox} {oy} {ox + w} {oy + h}
" f"imageSize={image.width} {image.height}
" "minFilter=linear
magFilter=linear
") level = 0 while True: cols = -(-image.width // PYRAMID_TILE) rows = -(-image.height // PYRAMID_TILE) z.writestr(f"{level}/", b"") for cx in range(cols): for cy in range(rows): tile = Image.new("RGBA", (PYRAMID_TILE, PYRAMID_TILE), (0, 0, 0, 0)) tile.paste(image.crop((cx * PYRAMID_TILE, cy * PYRAMID_TILE, min(image.width, (cx + 1) * PYRAMID_TILE), min(image.height, (cy + 1) * PYRAMID_TILE)))) raw = io.BytesIO() tile.save(raw, format="PNG") z.writestr(f"{level}/tile{cx}x{cy}.png", raw.getvalue()) if cols <= 3 and rows <= 3: break image = image.resize((max(1, -(-image.width // 2)), max(1, -(-image.height // 2))), Image.LANCZOS) level += 1 return True

def write_spawnpoints(project_dir: str, map_dir: str, limit: int = 8) -> int: """Write spawnpoints.lua, without which the map is not a startable region. Build 42's own maps use absolute world tile coordinates and a single `unemployed` list: function SpawnPoints() return { unemployed = { { posX = 2152, posY = 6089, posZ = 0 }, } } end (Older community maps use worldX/worldY cell coordinates plus an in-cell offset; that form still loads but is not what the shipped maps do.) Spawns go inside homes, spread across the town - see _spawn_tiles. """ points = _spawn_tiles(project_dir, limit) if not points: # No buildings: fall back to the centre of the map. info = None for entry in os.listdir(project_dir): if entry.endswith("_info.json"): info = os.path.join(project_dir, entry) break if info: import json as _json with open(info, encoding="utf-8") as f: meta = _json.load(f) points = [(meta["width_tiles"] // 2, meta["height_tiles"] // 2)] else: points = [(150, 150)] # Spawn points are absolute world tiles, so they must carry the same world # origin the lots were generated with. Without this they point at wherever # the map would have sat at origin 0,0 — on top of vanilla Knox County. ox, oy = _world_origin_tiles(project_dir) points = [(x + ox, y + oy) for x, y in points] body = ",
".join(f" {{ posX = {x}, posY = {y}, posZ = 0 }}" for x, y in points) lua = ("function SpawnPoints()
" " return {
" " unemployed = {
" f"{body}
" " }
" " }
" "end
") with open(os.path.join(map_dir, "spawnpoints.lua"), "w", encoding="utf-8") as f: f.write(lua) return len(points)

def write_objects(project_dir: str, map_dir: str) -> dict[str, int]: """Write objects.lua, the zones the game reads: ParkingStall is the only place a vehicle ever spawns, TownZone marks ground as town. The zones are in the WorldEd project, but compiling lots does not export them - maps went into the game with no objects.lua at all, and so without a single parked car. Written here from the project instead, in the form the game's own maps use: absolute world tiles. objects = { { name = "", type = "ParkingStall", x = 21040, y = 310, z = 0, width = 3, height = 5 }, } """ import re sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__)))) from knoxbuild.world import CELL_SIZE ox, oy = _world_origin_tiles(project_dir) pzw = next((os.path.join(project_dir, e) for e in sorted(os.listdir(project_dir)) if e.endswith(".pzw")), None) rows, counts = [], {} if pzw: cx = cy = None with open(pzw, encoding="utf-8", errors="replace") as f: for line in f: cell = re.search(r'<cell x="(-?\d+)" y="(-?\d+)"', line) if cell: cx, cy = int(cell.group(1)), int(cell.group(2)) continue if "<object " not in line or cx is None: continue attrs = dict(re.findall(r'(\w+)="([^"]*)"', line)) try: kind = attrs.get("type") or attrs["group"] x = ox + cx * CELL_SIZE + int(attrs["x"]) y = oy + cy * CELL_SIZE + int(attrs["y"]) z, w, h = int(attrs.get("level", 0)), int(attrs["width"]), int(attrs["height"]) except (KeyError, ValueError): continue if w <= 0 or h <= 0 or not re.fullmatch(r"\w+", kind): continue name = re.sub(r'[^\w ]', "", attrs.get("name", "")) rows.append(f' {{ name = "{name}", type = "{kind}", x = {x}, y = {y}, ' f'z = {z}, width = {w}, height = {h} }}') counts[kind] = counts.get(kind, 0) + 1 with open(os.path.join(map_dir, "objects.lua"), "w", encoding="utf-8") as f: f.write("objects = {
" + ",
".join(rows) + ("
